import React from 'react'
import { useAuth0 } from '@auth0/auth0-react';
import LoginButton from '../../components/page/login/LoginButton';
import Typography from '@mui/material/Typography';
import Stack from '@mui/material/Stack';
import Paper from '@mui/material/Paper';

const LoginPage = () => {  
    return (
        <Stack
        sx={{
            height: "100vh",                  // full viewport height
            justifyContent: "center",         // vertical center
            alignItems: "center",             // horizontal center
            bgcolor: "#f5f5f5",               // page background color
        }}
        >
        <Paper
            elevation={6}                     // subtle shadow
            sx={{
            p: { xs: 4, sm: 6, md: 8 },    // responsive padding
            borderRadius: 4,                // rounded corners
            border: "2px solid #ccc",       // border color
            textAlign: "center",            // center all text inside
            bgcolor: "#white",               // card background color
            minWidth: { xs: "90%", sm: "400px", md: "500px" }, // responsive width
            }}
        >
            <Typography
            variant="h2"
            component="h2"
            sx={{ mb: { xs: 4, sm: 6 } }}   // responsive bottom margin
            >
            Welcome to ChefGPT!
            </Typography>

            <LoginButton/>
        </Paper>
        </Stack>
  );
}

export default LoginPage
